                                                                                                                                                                                                      
  CREATE TABLE "TENANT_POINT"                                                                                                                                                              
   (	"POINT_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER,                                                                                                                                                                                 
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                
	"UPDATED_BY" NUMBER,                                                                                                                                                                                 
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                  
	"REMARK" NUMBER,                                                                                                                                                                                     
	"TENANT_ID" NUMBER DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                        
	"EXT_USER_ID" NUMBER NOT NULL ENABLE,                                                                                                                                                                
	"RECORD_SOURCE" VARCHAR2(50),                                                                                                                                                                        
	"REASON" VARCHAR2(100),                                                                                                                                                                              
	"OPERATION" VARCHAR2(30),                                                                                                                                                                            
	"EVENT_ID" NUMBER,                                                                                                                                                                                   
	"SCORE" NUMBER,                                                                                                                                                                                      
	"EXT_ORG_ID" NUMBER,                                                                                                                                                                                 
	"FAB_ID" NUMBER,                                                                                                                                                                                     
	"MAP_AREA_X_ID" NUMBER,                                                                                                                                                                              
	"MAP_AREA_Y_ID" NUMBER,                                                                                                                                                                              
	"USER_TYPE" VARCHAR2(30),                                                                                                                                                                            
	"RESOLVE_TIME" NUMBER,                                                                                                                                                                               
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                        
	 PRIMARY KEY ("POINT_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                 
   ) ;                                                                                                                                                                                                

